  "inlineSchema": "generator client {\n  provider = \"prisma-client-js\"\n  output   = \"../prismaClient\"\n}\n\ndatasource db {\n  provider = \"mysql\"\n  url      = env(\"DATABASE_URL\")\n}\n\nmodel Student {\n  id             String             @id @default(cuid())\n  code           String             @unique\n  firstName      String\n  lastName       String\n  email          String             @unique\n  password       String\n  classId        String?\n  class          Class?             @relation(fields: [classId], references: [id])\n  enrollments    CourseEnrollment[]\n  grades         Grade[]\n  attendances    Attendance[]\n  parentLinks    ParentStudent[]\n  gradeSummaries GradeSummary[]\n  studentAnswers StudentAnswer[]\n  notifications  Notification[]     @relation(\"StudentNotifications\")\n  createdAt      DateTime           @default(now())\n  updatedAt      DateTime           @updatedAt\n  deletedAt      DateTime?\n}\n\nmodel Teacher {\n  id            String           @id @default(cuid())\n  firstName     String\n  lastName      String\n  email         String           @unique\n  password      String\n  courses       CourseTeacher[]\n  assessments   Assessment[]\n  materials     CourseMaterial[]\n  notifications Notification[]   @relation(\"TeacherNotifications\")\n  createdAt     DateTime         @default(now())\n  updatedAt     DateTime         @updatedAt\n  deletedAt     DateTime?\n}\n\nmodel Parent {\n  id            String          @id @default(cuid())\n  firstName     String\n  lastName      String\n  email         String          @unique\n  password      String\n  parentLinks   ParentStudent[]\n  notifications Notification[]  @relation(\"ParentNotifications\")\n  createdAt     DateTime        @default(now())\n  updatedAt     DateTime        @updatedAt\n  deletedAt     DateTime?\n}\n\nmodel Admin {\n  id            String         @id @default(cuid())\n  firstName     String\n  lastName      String\n  email         String         @unique\n  password      String\n  notifications Notification[] @relation(\"AdminNotifications\")\n  createdAt     DateTime       @default(now())\n  updatedAt     DateTime       @updatedAt\n  deletedAt     DateTime?\n}\n\nmodel Director {\n  id            String         @id @default(cuid())\n  firstName     String\n  lastName      String\n  email         String         @unique\n  password      String\n  notifications Notification[] @relation(\"DirectorNotifications\")\n  createdAt     DateTime       @default(now())\n  updatedAt     DateTime       @updatedAt\n  deletedAt     DateTime?\n}\n\nmodel Guest {\n  id            String         @id @default(cuid())\n  firstName     String\n  lastName      String\n  email         String         @unique\n  password      String\n  notifications Notification[] @relation(\"GuestNotifications\")\n  createdAt     DateTime       @default(now())\n  updatedAt     DateTime       @updatedAt\n  deletedAt     DateTime?\n}\n\nmodel Class {\n  id       String    @id @default(cuid())\n  name     String\n  section  String?\n  students Student[]\n  courses  Course[]\n}\n\nmodel Course {\n  id             String             @id @default(cuid())\n  name           String\n  code           String             @unique\n  classId        String?\n  class          Class?             @relation(fields: [classId], references: [id])\n  enrollments    CourseEnrollment[]\n  teachers       CourseTeacher[]\n  assessments    Assessment[]\n  materials      CourseMaterial[]\n  attendances    Attendance[]\n  schedules      Schedule[]\n  gradeSummaries GradeSummary[]\n}\n\nmodel CourseEnrollment {\n  id         String   @id @default(cuid())\n  studentId  String\n  courseId   String\n  enrolledAt DateTime @default(now())\n  student    Student  @relation(fields: [studentId], references: [id])\n  course     Course   @relation(fields: [courseId], references: [id])\n\n  @@unique([studentId, courseId])\n}\n\nmodel CourseTeacher {\n  id        String  @id @default(cuid())\n  teacherId String\n  courseId  String\n  teacher   Teacher @relation(fields: [teacherId], references: [id])\n  course    Course  @relation(fields: [courseId], references: [id])\n\n  @@unique([teacherId, courseId])\n}\n\nmodel Assessment {\n  id        String         @id @default(cuid())\n  title     String\n  type      AssessmentType\n  courseId  String\n  teacherId String\n  date      DateTime\n  course    Course         @relation(fields: [courseId], references: [id])\n  teacher   Teacher        @relation(fields: [teacherId], references: [id])\n  grades    Grade[]\n  questions Question[]\n}\n\nenum AssessmentType {\n  EXAM\n  QUIZ\n  ASSIGNMENT\n  PROJECT\n  OTHER\n}\n\nmodel Question {\n  id             String          @id @default(cuid())\n  assessmentId   String\n  text           String\n  assessment     Assessment      @relation(fields: [assessmentId], references: [id])\n  studentAnswers StudentAnswer[]\n}\n\nmodel StudentAnswer {\n  id         String   @id @default(cuid())\n  questionId String\n  studentId  String\n  answer     String\n  question   Question @relation(fields: [questionId], references: [id])\n  student    Student  @relation(fields: [studentId], references: [id])\n}\n\nmodel Grade {\n  id           String     @id @default(cuid())\n  assessmentId String\n  studentId    String\n  value        Float\n  assessment   Assessment @relation(fields: [assessmentId], references: [id])\n  student      Student    @relation(fields: [studentId], references: [id])\n}\n\nmodel GradeSummary {\n  id        String  @id @default(cuid())\n  studentId String\n  courseId  String\n  average   Float\n  student   Student @relation(fields: [studentId], references: [id])\n  course    Course  @relation(fields: [courseId], references: [id])\n}\n\nmodel Attendance {\n  id        String           @id @default(cuid())\n  studentId String\n  courseId  String\n  date      DateTime\n  status    AttendanceStatus\n  student   Student          @relation(fields: [studentId], references: [id])\n  course    Course           @relation(fields: [courseId], references: [id])\n}\n\nenum AttendanceStatus {\n  PRESENT\n  ABSENT\n  LATE\n  EXCUSED\n}\n\nmodel CourseMaterial {\n  id          String  @id @default(cuid())\n  courseId    String\n  teacherId   String\n  title       String\n  description String?\n  url         String?\n  course      Course  @relation(fields: [courseId], references: [id])\n  teacher     Teacher @relation(fields: [teacherId], references: [id])\n}\n\nmodel Notification {\n  id         String           @id @default(cuid())\n  studentId  String?\n  teacherId  String?\n  parentId   String?\n  adminId    String?\n  directorId String?\n  guestId    String?\n  type       NotificationType\n  content    String\n  fileUrl    String?\n  createdAt  DateTime         @default(now())\n  // Relations\n  student    Student?         @relation(\"StudentNotifications\", fields: [studentId], references: [id])\n  teacher    Teacher?         @relation(\"TeacherNotifications\", fields: [teacherId], references: [id])\n  parent     Parent?          @relation(\"ParentNotifications\", fields: [parentId], references: [id])\n  admin      Admin?           @relation(\"AdminNotifications\", fields: [adminId], references: [id])\n  director   Director?        @relation(\"DirectorNotifications\", fields: [directorId], references: [id])\n  guest      Guest?           @relation(\"GuestNotifications\", fields: [guestId], references: [id])\n}\n\nenum NotificationType {\n  TEXT\n  IMAGE\n  FILE\n  ALERT\n  OTHER\n}\n\nmodel ParentStudent {\n  id        String  @id @default(cuid())\n  parentId  String\n  studentId String\n  parent    Parent  @relation(fields: [parentId], references: [id])\n  student   Student @relation(fields: [studentId], references: [id])\n\n  @@unique([parentId, studentId])\n}\n\nmodel Schedule {\n  id        String   @id @default(cuid())\n  courseId  String\n  startTime DateTime\n  endTime   DateTime\n  location  String?\n  course    Course   @relation(fields: [courseId], references: [id])\n}\n",
